package com.termux.app.workspace;
import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.RuntimeEnvironment;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiLimitsTest {
 @Test public void supportedLimitsAndEngineCapabilitiesAreExplicit(){for(int c:new int[]{4096,8192})for(int a:LocalAiLimits.ANSWERS)LocalAiLimits.engine("llama",c,a);LocalAiLimits.engine("litert",4096,2048);for(int[] pair:new int[][]{{8192,768},{4096,42}})try{LocalAiLimits.engine("litert",pair[0],pair[1]);fail();}catch(IllegalArgumentException expected){}}
 @Test public void budgetsPersistCopyAndDefaultFromOldProfiles()throws Exception{WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAi=true;p.environment="termux";p.localContext=8192;p.localMaxTokens=2048;store.sessions.add(p);JSONObject data=store.encode();store.decode(data.toString());assertEquals(8192,store.sessions.get(0).localContext);assertEquals(2048,store.sessions.get(0).localMaxTokens);assertEquals(8192,p.copy().localContext);assertEquals(2048,p.copy().localMaxTokens);JSONObject row=data.getJSONArray("sessions").getJSONObject(0);row.remove("localContext");row.remove("localMaxTokens");store.decode(data.toString());assertEquals(4096,store.sessions.get(0).localContext);assertEquals(768,store.sessions.get(0).localMaxTokens);}
 @Test public void malformedBudgetTypesAndNumbersAreRejected()throws Exception{for(Object bad:new Object[]{"8192",42,4096.5}){WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();store.sessions.add(new WorkspaceStore.Session());JSONObject data=store.encode();data.getJSONArray("sessions").getJSONObject(0).put("localContext",bad);try{store.decode(data.toString());fail(String.valueOf(bad));}catch(JSONException expected){}}}
 @Test public void findAndReadAliasesUseDirectPathWithoutGeneration()throws Exception{for(String text:new String[]{"привет найди ласт тхт в довнолоад и прочитай","find latest markdown in downloads and read it"}){JSONArray h=new JSONArray().put(new JSONObject().put("role","user").put("text",text));LocalAiRecent r=LocalAiRecent.parse(h);assertNotNull(text,r);assertTrue(r.read);WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";int[] runs={0};LocalAiAgent.run(p,h,new AtomicBoolean(),(a,s,o)->{throw new AssertionError("Unexpected model generation");},req->{runs[0]++;if(req.getString("tool").equals("locations"))return "exit=0\nAVAILABLE\t/sdcard/Download\n";if(req.getString("tool").equals("list"))return "exit=0\n{\"entries\":[{\"type\":\"file\",\"path\":\"/sdcard/Download/new."+r.extension+"\"}]}";return "exit=0\nLiteral contents";},req->false,new LocalAiSearchTest.Events(),t->{});assertEquals(3,runs[0]);}}
 @Test public void complexActionsNeverBecomeReadOnlyFastPath()throws Exception{for(String text:new String[]{"найди последний txt в загрузках и удали","найди последний txt в загрузках и прочитай и объясни","find latest txt in downloads and read it then run it"})assertNull(LocalAiRecent.parse(new JSONArray().put(new JSONObject().put("role","user").put("text",text))));}
 @Test public void timingsTrackPhasesAndLiveElapsedWithoutContent(){long[] clock={100};LocalAiTiming t=new LocalAiTiming(()->clock[0]);WorkspaceStore.Session p=new WorkspaceStore.Session();p.localContext=8192;p.localMaxTokens=1024;t.begin(p,"llama / CPU");clock[0]=180;t.phase("running:list");clock[0]=200;t.phase("context_preparation");clock[0]=220;t.phase("prefill");clock[0]=1000;t.text("private response not stored");clock[0]=2000;t.metrics(500,100);t.finish("finished");String report=t.report(false);assertTrue(report.contains("8192 / 1024"));assertTrue(report.contains("500 / 100"));assertFalse(report.contains("private response"));assertTrue(report.contains("1900 ms"));assertFalse(t.active);}
 @Test public void liteRtNeverInventsTokenCountsAndPausedEventsStayBounded(){long[] clock={1};LocalAiTiming t=new LocalAiTiming(()->clock[0]);t.begin(new WorkspaceStore.Session(),"litert / GPU");t.paused=true;clock[0]=99;t.phase("prefill");assertEquals(0,t.events.size());assertTrue(t.report(false).contains("— / —"));t.paused=false;for(int i=0;i<200;i++){clock[0]++;t.phase("stage"+i);}assertTrue(t.events.size()<=160);}
 @Test public void nativeProgressIsValidatedResetAndMetadataOnly()throws Exception{LocalAiTiming t=new LocalAiTiming(()->100L);WorkspaceStore.Session p=new WorkspaceStore.Session();t.begin(p,"llama / CPU");JSONObject data=new JSONObject().put("total",100).put("processed",80).put("cached",40).put("prefillMs",50).put("cacheMs",2).put("firstTokenMs",-1).put("cacheStatus","warm_prefix");t.performance(data.toString());assertEquals(80,t.processed);assertTrue(t.report(false).contains("80 / 100"));data.put("processed",101);t.performance(data.toString());assertEquals(80,t.processed);data.put("processed",90).put("prefillMs",-1);t.performance(data.toString());assertEquals(80,t.processed);t.phase("first_token");t.text("secret text");assertEquals("generation",t.phase);assertFalse(t.report(false).contains("secret text"));t.finish("finished");data.put("processed",90).put("prefillMs",60);t.performance(data.toString());assertEquals(80,t.processed);t.begin(p,"litert / GPU");assertEquals(-1,t.processed);assertEquals(-1,t.firstStepMs);assertEquals("",t.cacheStatus);assertTrue(t.report(false).contains("Cached input: —"));}
 @Test public void perPassReportsRetainCacheAndDistinguishActiveCompletedAndAborted()throws Exception{long[] clock={100};LocalAiTiming t=new LocalAiTiming(()->clock[0]);t.begin(new WorkspaceStore.Session(),"llama / CPU");t.phase("context_preparation");t.phase("prefill");t.performance(new JSONObject().put("total",2000).put("processed",2000).put("cached",1000).put("prefillMs",30000).put("cacheMs",20).put("firstTokenMs",1).put("cacheStatus","prefix_snapshot").toString());clock[0]=30100;t.text("private answer");clock[0]=31100;t.metrics(2000,20);t.phase("postprocessing");t.phase("running:read");clock[0]=32000;t.phase("context_preparation");t.phase("prefill");t.performance(new JSONObject().put("total",2400).put("processed",2000).put("cached",1900).put("prefillMs",300).put("cacheMs",10).put("firstTokenMs",-1).put("cacheStatus","prefix_snapshot").toString());String report=t.report(false);assertTrue(report.contains("Pass 1 · completed"));assertTrue(report.contains("2000 / 2000 / 1000 / 1000"));assertTrue(report.contains("30000 / 20 / 0 / 1"));assertTrue(report.contains("Pass 2 · in progress"));assertTrue(report.contains("2400 / 2000 / 1900 / 500"));assertFalse(report.contains("private answer"));t.finish("error");assertEquals(2,t.passes.size());assertTrue(t.report(false).contains("Pass 2 · not completed"));assertTrue(t.report(true).contains("Проход 1 · завершён"));assertFalse(t.report(false).contains("in progress"));t.finish("error");assertEquals(2,t.passes.size());t.begin(new WorkspaceStore.Session(),"litert / GPU");assertEquals(0,t.passes.size());t.phase("context_preparation");t.phase("prefill");t.text("text");t.phase("postprocessing");assertTrue(t.report(false).contains("— / — / — / —"));assertTrue(t.report(false).contains("Pass 1 · completed"));}
 @Test public void perPassHistoryIsBoundedAndPauseSkipsArchiving(){LocalAiTiming t=new LocalAiTiming(()->100L);t.begin(new WorkspaceStore.Session(),"llama / CPU");for(int i=0;i<70;i++){t.phase("context_preparation");t.phase("postprocessing");}assertEquals(64,t.passes.size());assertEquals(6,t.omittedPasses);assertTrue(t.report(false).contains("Older passes omitted: 6"));t.paused=true;t.phase("context_preparation");t.phase("postprocessing");t.finish("finished");assertEquals(64,t.passes.size());assertFalse(t.report(false).contains("Pass 71"));}
 @Test public void cpuEngineModeDefaultsPersistsAndCopiesWithoutChangingBackendOrRights()throws Exception{WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAi=true;p.environment="termux";p.localCpu="compatible";p.localBackend="cpu";p.localAccess="read";store.sessions.add(p);String json=store.encode().toString();store.decode(json);assertEquals("compatible",store.sessions.get(0).localCpu);assertEquals("compatible",p.copy().localCpu);assertEquals("cpu",store.sessions.get(0).localBackend);assertEquals("read",store.sessions.get(0).localAccess);JSONObject old=new JSONObject(json);old.getJSONArray("sessions").getJSONObject(0).remove("localCpu");store.decode(old.toString());assertEquals("auto",store.sessions.get(0).localCpu);}
 @Test public void invalidCpuEngineModeAndTypesAreRejected()throws Exception{LocalAiEngine.validateCpuMode("auto");LocalAiEngine.validateCpuMode("compatible");for(Object bad:new Object[]{"fast","gpu",2,JSONObject.NULL}){WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();store.sessions.add(new WorkspaceStore.Session());JSONObject json=store.encode();json.getJSONArray("sessions").getJSONObject(0).put("localCpu",bad);try{store.decode(json.toString());fail(String.valueOf(bad));}catch(JSONException expected){}}}
 @Test public void cpuThreadsPersistDefaultCopyAndClampToAvailableProcessors()throws Exception{WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();WorkspaceStore.Session p=new WorkspaceStore.Session();p.localThreads=6;store.sessions.add(p);JSONObject data=store.encode();store.decode(data.toString());assertEquals(6,store.sessions.get(0).localThreads);assertEquals(6,p.copy().localThreads);assertEquals(6,new LocalAiUi.Selection(p).threads);assertEquals(6,LocalAiCpu.resolve(6,8));assertEquals(4,LocalAiCpu.resolve(0,8));assertEquals(2,LocalAiCpu.resolve(8,2));assertEquals(1,LocalAiCpu.resolve(0,0));data.getJSONArray("sessions").getJSONObject(0).remove("localThreads");store.decode(data.toString());assertEquals(0,store.sessions.get(0).localThreads);}
 @Test public void cpuThreadsRejectInvalidPersistedValues()throws Exception{for(Object bad:new Object[]{-1,3,9,"6",6.5,JSONObject.NULL}){WorkspaceStore store=new WorkspaceStore(RuntimeEnvironment.application,x->{});store.sessions.clear();store.sessions.add(new WorkspaceStore.Session());JSONObject data=store.encode();data.getJSONArray("sessions").getJSONObject(0).put("localThreads",bad);try{store.decode(data.toString());fail(String.valueOf(bad));}catch(JSONException expected){}}}
}
